<section class="container section-top"><nav class="breadcrumbs" aria-label="<?=e(t('breadcrumbs'))?>"><a href="<?=e(url('home'))?>"><?=e(t('home'))?></a><span>/</span><a href="<?=e(url(match($item['kind']??'service'){'trainer'=>'trainers','facility'=>'facilities','news'=>'news',default=>'services'}))?>"><?=e(t($item['kind']??'service'))?></a><span>/</span><span><?=e($item['title'])?></span></nav><div class="detail-grid"><div><p class="eyebrow"><?=e(t($item['category']??$item['kind']))?></p><h1><?=e($item['title'])?></h1><p class="lede"><?=e($item['summary']??'')?></p><div class="badge-row"><?php if(!empty($item['level']))ff_badge($item['level'],'muted'); if(!empty($item['format']))ff_badge($item['format'],'muted'); ?></div><?php if(($item['kind']??'')==='news'): ?><p class="article-meta"><span><?=e(t('author'))?>: <?=e(t($item['author']??'Project team'))?></span><?php if(!empty($item['published_at'])): ?><span><?=e(t('published_date'))?>: <?=e(local_time($item['published_at'],'d M Y'))?></span><?php endif ?></p><?php endif ?><div class="prose"><?=nl2br(e($item['body']??''))?></div><?php $meta=is_array($item['metadata']??null)?$item['metadata']:(json_decode($item['metadata']??'{}',true)??[]); if($meta): ?><dl class="detail-facts"><?php foreach($meta as $key=>$value): if(is_scalar($value)&&!in_array($key,['source_status','illustration'],true)): ?><div><dt><?=e(t($key))?></dt><dd><?=e(t((string)$value))?></dd></div><?php endif; endforeach ?></dl><?php endif ?><div class="button-row"><a class="button dark" href="<?=e(url(($item['kind']??'')==='trainer'?'classes':'contact'))?>"><?=e(t(($item['kind']??'')==='trainer'?'view_schedule':'make_an_inquiry'))?> <?=ff_icon()?></a><?php if(in_array($item['kind']??'',['service','trainer','class_type']))ff_favorite($item,$isFavorite??false); ?></div><?php if(($item['kind']??'')==='news'): ?><div class="share-row"><button class="text-link link-button" data-share type="button"><?=e(t('share_article'))?> <?=ff_icon()?></button><span data-share-status role="status"></span></div><?php endif ?></div><div class="detail-visual"><img class="<?=e(ff_image_class($item))?>" src="<?=e(ff_image($item,($item['kind']??'')==='trainer'?'trainer-avatar.svg':'gym-scene.svg'))?>" alt="<?=e(ff_image_alt($item))?>" width="720" height="780"><p class="fine-print"><?=e(ff_image_alt($item))?></p></div></div><?php if(!empty($relatedSessions)): ?><section class="section"><h2><?=e(t('related_classes'))?></h2><?php foreach($relatedSessions as $session)ff_class_row($session); ?></section><?php endif ?><?php if(!empty($relatedPeople)): ?><section class="section"><h2><?=e(t('related_trainers'))?></h2><div class="card-grid three"><?php foreach($relatedPeople as $person)ff_card($person); ?></div></section><?php endif ?><?php if(!empty($relatedServices)): ?><section class="section"><h2><?=e(t('related_services'))?></h2><div class="card-grid three"><?php foreach($relatedServices as $service)ff_card($service); ?></div></section><?php endif ?><?php if(!empty($related)): ?><section class="section"><h2><?=e(t('related'))?></h2><div class="card-grid three"><?php foreach($related as $item)ff_card($item); ?></div></section><?php endif ?></section>
